    required this.iso6393,
    required this.iso6391,
    required this.name,
  });

  /// Three-letter code. Voracious's canonical language identifier.
  final String iso6393;

  /// Two-letter code.
  final String iso6391;

  /// English name.
  final String name;

  @override
  String toString() => '$name ($iso6393)';
}

