/// The code ISO 639-3 reserves for "could not be determined".
const String undeterminedLanguage = 'und';

/// Looks up a language by its three-letter code.
LanguageEntry? languageByIso6393(String code) =>
    _byIso6393[code.trim().toLowerCase()];

/// Looks up a language by its two-letter code.
LanguageEntry? languageByIso6391(String code) =>
    _byIso6391[code.trim().toLowerCase()];

/// Converts a two- or three-letter code to the canonical three-letter form,
/// returning null if it is neither.
String? toIso6393(String code) {
  final normalized = code.trim().toLowerCase();
  if (_byIso6393.containsKey(normalized)) return normalized;
  return _byIso6391[normalized]?.iso6393;
}

/// Converts a three-letter code to its two-letter form, if it has one.
String? toIso6391(String iso6393) =>
    _byIso6393[iso6393.trim().toLowerCase()]?.iso6391;

/// English name for a two- or three-letter code.
String? languageName(String code) {
  final normalized = code.trim().toLowerCase();
  return (_byIso6393[normalized] ?? _byIso6391[normalized])?.name;
}
